insert into public.guide_stories (id, position, title, summary, official_name, official_url) values
  ('election-date', 0, 'INEC moves the presidential election to 16 January 2027', 'INEC set the presidential and National Assembly elections for Saturday 16 January 2027. They had been set for 20 February 2027. INEC said the Electoral Act 2026 changed statutory timelines.', 'INEC: Election calendar', 'https://inecnigeria.org/elections/calendar'),
  ('candidate-list', 1, 'INEC publishes the list of presidential candidates', 'Press reports on 12 and 13 September 2026 described 18 candidates. INEC''s current list, which the Candidates page uses, has 18 named candidates and one row without a name.', 'INEC: Final list of candidates, Presidential', 'https://inecnigeria.org/press/updated-list-of-candidates-for-2027-presidential-election')
