insert into public.guide_candidate_items (id, candidate_id, kind, title, url, publisher, publisher_type, published_on, checked_on, opinion, language, occasion, place, length, excerpt) values
  ('tinubu-speech-accept-apc', 'tinubu-bola-ahmed', 'speech', 'Acceptance speech on his nomination as APC presidential flagbearer for the 2027 election', 'https://statehouse.gov.ng/acceptance-speech-by-president-bola-ahmed-tinubu-gcfr-on-his-nomination-as-apc-presidential-flagbearer-for-the-2027-election-delivered-on-sunday-may-24-2026/', 'State House, Abuja', 'official', '2026-05-24', '2026-11-20', false, 'English', 'Acceptance speech', 'Abuja', null, 'Today, we celebrate another proud moment in our democratic journey—a history not defined by any individual, but by our collective resolve to build a stable, prosperous, and just nation.'),
  ('makinde-speech-accept-apm', 'makinde-oluseyi-abiodun', 'speech', 'Acceptance speech as Allied Peoples'' Movement presidential candidate', 'https://seyimakinde.com/allied-peoples-movement-presidential-candidate/', 'seyimakinde.com', 'candidate', '2026-05-30', '2026-11-20', false, 'English', 'Acceptance speech', null, null, 'I stand before you today with deep humility and a profound sense of responsibility as I accept the nomination to serve as the Presidential Candidate of the Allied Peoples’ Movement for the Federal Republic of Nigeria.'),
  ('atiku-speech-accept-adc', 'abubakar-atiku', 'speech', 'Speech after emerging ADC presidential candidate for the 2027 election (full text)', 'https://www.legit.ng/politics/1711961-full-text-atikus-speech-emerging-adc-presidential-candidate-2027-election/', 'Legit.ng', 'outlet', '2026-05-28', '2026-11-20', false, 'English', 'Acceptance speech', 'Abuja', null, 'I wish to express my profound appreciation for the privilege which you have bestowed on me, of leading our great party, the African Democratic Congress, into the next elections as its Presidential Candidate.'),
  ('obi-speech-accept-ndc', 'obi-peter-gregory', 'speech', 'Speech after emerging NDC presidential candidate for the 2027 election (full text)', 'https://www.legit.ng/politics/1712331-full-text-peter-obis-speech-emerging-ndc-presidential-candidate-2027-election/', 'Legit.ng', 'outlet', '2026-05-30', '2026-11-20', false, 'English', 'Acceptance speech', 'Abuja', null, 'Esteemed citizens of Nigeria, It is with deep humility that I accept the role of presidential candidate for our party.'),
  ('tinubu-video-accept-apc', 'tinubu-bola-ahmed', 'video', 'Tinubu’s Acceptance Speech as APC 2027 Presidential Nominee', 'https://www.youtube.com/watch?v=H6mx7BVzT_M', 'RootsTV Nigeria', 'outlet', '2026-05-24', '2026-11-20', false, null, 'Acceptance speech', null, null, null),
  ('makinde-video-accept-apm', 'makinde-oluseyi-abiodun', 'video', 'Governor Seyi Makinde''s Acceptance Speech as the APM Presidential Candidate - 30/05/2026', 'https://www.youtube.com/watch?v=iYYg5fauhUk', 'Seyi Makinde', 'candidate', '2026-05-30', '2026-11-20', false, null, 'Acceptance speech', null, null, null),
  ('atiku-video-accept-adc', 'abubakar-atiku', 'video', 'Full Speech 2027 Elections Atiku Abubakar Emerges ADC Candidate, Defeats Amaechi & Hayatu Deen', 'https://www.youtube.com/watch?v=wV9wfTLuzxE', 'marvellscreation tv', 'outlet', '2026-05-28', '2026-11-20', false, null, 'Acceptance speech', null, null, null),
  ('obi-video-accept-ndc', 'obi-peter-gregory', 'video', 'PETER OBI’S ACCEPTANCE SPEECH AS THE PRESIDENTIAL CANDIDATE AT THE NDC SPECIAL CONVENTION 2026', 'https://www.youtube.com/watch?v=mEAYPn4a9YI', 'Njenje Media TV', 'outlet', '2026-05-30', '2026-11-20', false, null, 'Acceptance speech', null, null, null)
